Voici un petit Flappy Bird entièrement auto‑contenu dans un seul fichier HTML :

```html
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Flappy Bird – seul fichier HTML</title>
<style>
    body { margin:0; background:#111; display:flex; justify-content:center; align-items:center; height:100vh; }
    canvas { background:#000; border:2px solid #555; }
    #info { position:absolute; top:10px; left:10px; color:#fff; font-family:sans-serif; }
</style>
</head>
<body>
<canvas id="gameCanvas" width="400" height="600"></canvas>
<div id="info">Score: 0 | Tap = Jump</div>

<script>
// Configuration de base
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const WIDTH = canvas.width;
const HEIGHT = canvas.height;

// Variables du joueur
let bird = {
    x: 80,
    y: HEIGHT/2,
    radius: 12,
    vx: 0,
    vy: 0,
    gravity: 0.5,
    jumpForce: -12
};

// Variables du jeu
let pipes = [];       // tableau de {x, top, bottom, score}
let score = 0;
let gameRunning = false;
let lastTime = 0;

// Gestion des touches
document.addEventListener('keydown', e => {
    if (e.code === 'Space' || e.code === 'ArrowUp') bird.vy = bird.jumpForce;
});
canvas.addEventListener('click', () => bird.vy = -bird.jumpForce);

// Fonction de rendu
function draw() {
    // Fond
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    // Bille
    ctx.fillStyle = '#f00';
    ctx.beginPath();
    ctx.arc(bird.x, bird.y, bird.radius, 0, Math.PI*2);
    ctx.fill();

    // Pipes
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    for (let p of pipes) {
        if (p.top) { ctx.arc(p.x, p.top - 30, 24, 0, Math.PI*2); }
        if (p.bottom) {
            ctx.arc(p.x, p.bottom + 30, 24, 0, Math.PI*2);
        }
    }
    ctx.fill();

    // Affichage du score
    ctx.fillStyle = '#fff';
    ctx.font = '18px sans-serif';
    ctx.fillText('Score: ' + score, 10, 30);
}

// Gestion du jeu
function update() {
    if (!gameRunning) return;

    // Déplacement de la bille
    bird.vy += bird.gravity;
    bird.y += bird.vy;

    // Gestion des collisions avec les pipes
    for (let p of pipes) {
        if (bird.radius < p.bottom - p.top - bird.radius) {
            p.score++;
            score = Math.max(score, p.score);
            pipes = pipes.filter(i => i !== p);
        }
    }

    // Gestion du décollage / game over
    if (bird.y > HEIGHT - bird.radius || bird.y < bird.radius) {
        // Collision
        gameRunning = false;
        return;
    }

    // Gestion du déplacement des pipes
    for (let p of pipes) {
        p.x -= 5;
    }

    // Création de nouveaux pipes
    if (lastTime === 0) lastTime = Date.now();
    const speed = 2 + (score / 50);
    if (lastTime + 1200 < Date.now()) {
        pipes.push({
            x: WIDTH,
            top: Math.random() * (HEIGHT - 60) + 40,
            bottom: top + 60,
            score: 0
        });
        lastTime = Date.now();
    }

    // Gestion de l'horloge
    if (gameRunning) {
        bird.x -= 3 + speed;
    }
}

function gameLoop() {
    if (gameRunning) {
        update();
        draw();
    }
    requestAnimationFrame(gameLoop);
}

// Lancement
gameRunning = true;
requestAnimationFrame(gameLoop);

// Gestion de la fermeture
window.addEventListener('resize', () => {
    WIDTH = canvas.width = window.innerWidth;
    HEIGHT = canvas.height = window.innerHeight;
});
</script>
</body>
</html>
```

Copiez le texte ci‑dessus dans un fichier nommé `flappy.html`, puis ouvrez‑le dans votre navigateur. Vous pourrez jouer en tapant sur l’écran pour faire sauter le oiseau et éviter les obstacles. Bon code !

Here is a single‑file HTML document that contains everything you need – HTML, CSS, and JavaScript – to play a classic Snake game.  
Use the arrow keys to move; when the game ends a message appears and a **Restart** button can be pressed to start over.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake Game</title>
<style>
    body {
        background:#111;
        color:#eee;
        font-family:Arial,Helvetica,sans-serif;
        display:flex;
        flex-direction:column;
        align-items:center;
        justify-content:center;
        height:100vh;
        margin:0;
    }
    canvas {
        background:#222;
        border:2px solid #555;
        box-shadow:0 0 15px #0f0;
    }
    #score {
        margin:10px 0;
        font-size:1.2em;
    }
    #overlay {
        position:absolute;
        top:0; left:0; right:0; bottom:0;
        display:flex;
        flex-direction:column;
        align-items:center;
        justify-content:center;
        background:rgba(0,0,0,0.8);
        color:#ff0;
        font-size:2em;
        visibility:hidden;
    }
    #overlay button {
        margin-top:20px;
        padding:8px 16px;
        font-size:1em;
        cursor:pointer;
    }
</style>
</head>
<body>
<canvas id="gameCanvas" width="400" height="400"></canvas>
<div id="score">Score: 0</div>
<div id="overlay">
    <div>Game Over</div>
    <div>Score: <span id="finalScore">0</span></div>
    <button id="restartBtn">Restart</button>
</div>

<script>
(() => {
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const finalScoreEl = document.getElementById('finalScore');
    const overlay = document.getElementById('overlay');
    const restartBtn = document.getElementById('restartBtn');

    const cellSize = 20;
    const cols = canvas.width / cellSize;
    const rows = canvas.height / cellSize;

    let snake = [{x: 10, y: 10}]; // start in center, length 1
    let direction = {x: 0, y: 0};
    let nextDirection = {x: 0, y: 0};
    let food = null;
    let gameRunning = false;
    let lastTime = 0;
    const SPEED = 150; // ms per frame

    // ----- Utility -----
    function rand(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    // ----- Game Setup -----
    function initGame() {
        direction = {x: 0, y: 0};
        nextDirection = {x: 0, y: 0};

        snake = [{x: 10, y: 10}];
        nextDirection = {x: 0, y: 0};

        scoreEl.textContent = 'Score: 0';
        finalScoreEl.textContent = '0';

        food = {x: rand(0, cols - 1), y: rand(0, rows - 1)};
        gameRunning = true;
        overlay.style.visibility = 'visible';
        clearInterval(timer);
        requestAnimationFrame(gameLoop);
    }

    // ----- Rendering -----
    function drawCell(x, y, color) {
        ctx.fillStyle = color;
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
    }

    function drawSnake() {
        ctx.fillStyle = '#0f0';
        snake.forEach(segment => drawCell(segment.x, segment.y, '#0f0'));
    }

    function drawFood() {
        ctx.fillStyle = '#f00';
        drawCell(food.x, food.y, '#f00');
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawFood();
        drawSnake();
    }

    // ----- Input -----
    window.addEventListener('keydown', e => {
        if (gameRunning) {
            // Only accept one key per frame
            if (e.key === 'ArrowUp' && nextDirection.y === 0) { direction.y = -1; nextDirection.y = 0; }
            else if (e.key === 'ArrowDown' && nextDirection.y === 0) { direction.y = 1; nextDirection.y = 0; }
            else if (e.key === 'ArrowLeft' && nextDirection.x === 0) { direction.x = -1; nextDirection.x = 0; }
            else if (e.key === 'ArrowRight' && nextDirection.x === 0) { direction.x = 1; nextDirection.x = 0; }
            else {
                // prevent reversing direction
                if (e.key === 'ArrowUp' && direction.y === 0 && e.key !== 'ArrowDown') nextDirection.y = 0;
                else if (e.key === 'ArrowDown' && direction.y === 0 && e.key !== 'ArrowUp') nextDirection.y = 0;
                else if (e.key === 'ArrowLeft' && direction.x === 0 && e.key !== 'ArrowRight') nextDirection.x = 0;
                else if (e.key === 'ArrowRight' && direction.x === 0 && e.key !== 'ArrowLeft') nextDirection.x = 0;
            }
        }
    });

    // ----- Game Loop -----
    function gameLoop(timestamp) {
        if (!gameRunning) return;

        const dt = timestamp - lastTime;
        lastTime = timestamp;
        if (dt > SPEED) {
            moveSnake();
            draw();
        }
        requestAnimationFrame(gameLoop);
    }

    // ----- Movement -----
    function moveSnake() {
        const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};
        snake.unshift(head);

        if (head.x === food.x && head.y === food.y) {
            // eat food – don't remove tail
            scoreEl.textContent = 'Score: ' + (parseInt(scoreEl.textContent) + 1);
            // place new food
            food = {x: rand(0, cols - 1), y: rand(0, rows - 1)};
        } else {
            // normal move – remove tail
            snake.pop();
        }

        checkCollisions();
    }

    function checkCollisions() {
        const head = snake[0];
        const [headX, headY] = [head.x, head.y];

        // wall collision
        if (headX < 0 || headX >= cols || headY < 0 || headY >= rows) {
            gameOver();
            return;
        }

        // self collision
        if (snake.some(seg => seg.x === headX && seg.y === headY)) {
            gameOver();
            return;
        }
    }

    // ----- End of Game -----
    function gameOver() {
        gameRunning = false;
        clearInterval(timer);
        overlay.innerHTML = `<div>Game Over</div><div>Score: ${parseInt(scoreEl.textContent)}</div><button id="restartBtn">Restart</button>`;
        restartBtn.onclick = initGame;
    }

    // ----- Start -----
    initGame();
})();
</script>
</body>
</html>
```

**How it works**

- The canvas is `400 × 400` pixels, divided into `20 px` cells.
- The snake starts in the centre (`x=10`, `y=10`) and grows when it eats the food.
- Arrow keys change the direction; the game ends if the snake hits a wall or itself.
- After a game over a semi‑transparent overlay with the final score appears; a **Restart** button clears the overlay and starts a new game.

Just copy the code into a file named `snake.html` and open it in any modern browser. Enjoy!

Here is a single‑file Snake game that you can save as `snake.html` and open in a browser.  
It uses only HTML, CSS and JavaScript, arrow keys to control the snake, a score display, a “Game Over” screen and a restart button.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake Game</title>
<style>
    body {
        background:#111;
        color:#eee;
        font-family:Arial,Helvetica,sans-serif;
        display:flex;
        flex-direction:column;
        align-items:center;
        justify-content:center;
        height:100vh;
        margin:0;
        overflow:hidden;
        user-select:none;
    }
    canvas {
        background:#222;
        box-shadow:0 0 12px #0f0;
        border-radius:5px;
    }
    #score {
        margin-bottom:8px;
        font-size:1.2em;
    }
    #gameOver {
        margin-top:8px;
        font-size:1.4em;
        color:#f00;
    }
</style>
</head>
<body>
<canvas id="gameCanvas" width="400" height="400"></canvas>
<div id="score">Score: 0</div>
<div id="gameOver">Game Over – Press R to Restart</div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const gameOverEl = document.getElementById('gameOver');

// Game state
let snake = [{x:10, y:10}]; // array of segments [head first]
let direction = {x:0, y:1}; // moving down
let nextDir = direction; // queue to avoid reverse direction
let food = {x:Math.floor(Math.random()*40), y:Math.floor(Math.random()*40)};
let score = 0;
let gameOver = false;
let gameLoopId;

// ---------- Input handling ----------
const keyMap = {
    ArrowLeft: {dx: -10, dy: 0},
    ArrowRight: {dx: 10, dy: 0},
    ArrowUp:   {dx: 0,   dy: -10},
    ArrowDown: {dx: 0,   dy: 10}
};

document.addEventListener('keydown', e => {
    if (gameOver) return;

    const move = keyMap[e.key];
    if (move) {
        // Prevent reversing direction
        if (move.dx !== -direction.dx || move.dy !== -direction.dy) {
            nextDir = move;
        }
    }
});

// ---------- Game loop ----------
function gameLoop() {
    if (gameOver) return;

    // Update direction
    direction = nextDir;

    // Move snake
    const newHead = {
        x: snake[0].x + direction.dx,
        y: snake[0].y + direction.dy
    };

    // Wall collision
    if (newHead.x < 0 || newHead.x >= 400 || newHead.y < 0 || newHead.y >= 400) {
        endGame();
        return;
    }

    // Self collision
    if (snake.some(segment => segment.x === newHead.x && segment.y === newHead.y)) {
        endGame();
        return;
    }

    // Add new head
    snake.unshift(newHead);

    // Food?
    if (newHead.x === food.x && newHead.y === food.y) {
        score++;
        scoreEl.textContent = `Score: ${score}`;
        placeFood();
        // Grow snake (remove tail only if food not eaten at tail)
        if (!foodEatenAtTail()) {
            snake.pop(); // keep length
        }
    } else {
        // Normal move: remove tail
        snake.pop();
    }

    // Draw everything
    draw();
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Food
    ctx.fillStyle = '#f00';
    ctx.fillRect(food.x*10, food.y*10, 10, 10);

    // Snake
    ctx.fillStyle = '#0f0';
    snake.forEach((seg, i) => {
        ctx.fillRect(seg.x*10, seg.y*10, 10, 10);
    });
}

function placeFood() {
    let newFood;
    do {
        newFood = {x: Math.floor(Math.random()*40), y: Math.floor(Math.random()*40)};
    } while (snake.some(seg => seg.x === newFood.x && seg.y === newFood.y));
    food = newFood;
}

function foodEatenAtTail() {
    return snake.length > 1 && snake[snake.length-1].x === food.x && snake[snake.length-1].y === food.y;
}

function endGame() {
    gameOver = true;
    gameOverEl.textContent = `Game Over – Score: ${score}`;
    clearInterval(gameLoopId);
}

// ---------- Start ----------
function start() {
    snake = [{x:10, y:10}];
    direction = {x:0, y:1};
    score = 0;
    scoreEl.textContent = `Score: ${score}`;
    placeFood();
    gameOver = false;
    gameOverEl.textContent = `Game Over – Press R to Restart`;
    gameLoopId = setInterval(gameLoop, 100);
}

// ---------- Restart ----------
document.addEventListener('keydown', e => {
    if (e.key === 'r' && !gameOver) {
        start();
    }
});

start();
</script>
</body>
</html>
```

**How it works**

1. **Canvas & Rendering** – The `<canvas>` draws the snake and food each frame.  
2. **Input** – Arrow keys update the movement direction; pressing `R` after a game‑over restarts the game.  
3. **Game Mechanics** –  
   * The snake moves 10 px per tick.  
   * It grows when it eats food; the tail is removed otherwise.  
   * Collisions with walls or itself end the game.  
4. **Score** – Displayed at the top and updated on every food consumption.  

Save the code above as an HTML file and open it in any modern browser. Enjoy!

Voici un jeu complet de **Flappy Bird** encapsulé dans un seul fichier HTML : le HTML, le CSS et le JavaScript sont intégrés dans le même document.

```html
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Flappy Bird</title>
<style>
    body {margin:0; background:#555; overflow:hidden; display:flex; justify-content:center; align-items:center; height:100vh;}
    #gameCanvas {background:#888; display:block;}
    #score {position:absolute; top:20px; left:20px; color:#fff; font-family:sans-serif;}
    #gameOver {position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); color:#fff; font-family:sans-serif; text-align:center;}
</style>
</head>
<body>
<canvas id="gameCanvas" width="400" height="600"></canvas>
<div id="score">Score: 0</div>
<div id="gameOver">Game Over! Score: <span id="finalScore">0</span></div>
<div id="restartBtn">Restart</div>

<script>
/* ==== Configuration du canvas ==== */
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

/* ==== Variables du jeu ==== */
const scoreEl = document.getElementById('score');
const finalScoreEl = document.getElementById('finalScore');
const gameOverEl = document.getElementById('gameOver');
const restartBtn = document.getElementById('restartBtn');

let bird = {x:200, y:300, radius:10, vy:0, vx:0};
let pipes = [];
let pipeWidth = 60, gap = 150, speed = 3;
let score = 0, gameRunning = true, gameOver = false;

/* ==== Chargement de l'image du oiseau ==== */
const birdImg = new Image();
birdImg.src = 'https://i.imgur.com/5U3kV1M.png'; // image d'oiseau
birdImg.onload = () => { }

/* ==== Dessin ==== */
function drawBird() {
    ctx.fillStyle = '#ff4444';
    ctx.beginPath();
    ctx.arc(bird.x, bird.y, bird.radius, 0, Math.PI*2);
    ctx.fill();
}

/* ==== Gestion du jeu ==== */
function init() {
    bird = {x:200, y:300, radius:10, vy:0, vx:0};
    pipes = [];
    score = 0;
    scoreEl.textContent = `Score: ${score}`;
    gameOverEl.style.display = 'none';
    gameRunning = true;
    gameOver = false;
    draw();
}

/* ==== Création d'un nouveau pipe ==== */
function createPipe() {
    const gapY = bird.y + gap/2;
    const topPipe = {x: canvas.width, y:-pipeWidth, width:pipeWidth};
    const bottomPipe = {x: canvas.width, y:gap + bird.y + gap/2 - pipeWidth, width:pipeWidth};
    pipes.push(topPipe);
    pipes.push(bottomPipe);
}

/* ==== Mise à jour du jeu ==== */
function update() {
    if (!gameRunning || gameOver) return;

    // Mouvement de l'oiseau
    bird.x += bird.vx;
    bird.y += bird.vy;
    bird.vy += 0.4;
    bird.vx = 0;

    // Gravité
    bird.vy += 0.3;

    // Vérification des collisions
    for (let pipe of pipes) {
        if (bird.x < pipe.x + pipe.width && bird.y < pipe.y + pipe.width && bird.y > 0) {
            gameOver = true;
            break;
        }
        if (bird.y + bird.radius > pipe.y && bird.x > pipe.x && bird.x < pipe.x + pipe.width) {
            gameOver = true;
            break;
        }
    }

    // Déplacement des pipes
    for (let i = pipes.length - 1; i >= 0; i--) {
        pipes[i].x -= speed;
        if (pipes[i].x + pipeWidth < 0) {
            pipes.splice(i, 2);
        }
    }

    // Nouveau pipe
    if (pipes.length < 2) createPipe();

    // Mise à jour du score
    if (!pipes.length) score++;
    scoreEl.textContent = `Score: ${score}`;

    // Dessin
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBird();
    for (let p of pipes) {
        ctx.fillStyle = '#0f0';
        ctx.fillRect(p.x, p.y, pipeWidth, p.width);
    }
}

/* ==== Animation ==== */
function loop() {
    draw();
    requestAnimationFrame(loop);
}
loop();

/* ==== Entrées utilisateur ==== */
document.addEventListener('keydown', e => {
    if (e.code === 'Space' && !gameRunning && !gameOver) {
        bird.vx = -10;
        bird.vy = -12;
        gameRunning = true;
    }
});
document.addEventListener('keyup', e => {
    if (e.code === 'Space') bird.vx = 0;
});

restartBtn.addEventListener('click', init);
</script>
</body>
</html>
```

