content:
Voici une application todo list complète, écrite dans un seul fichier **HTML**.  
Elle permet :

* d’ajouter une tâche,
* de cocher/décocher une tâche terminée,
* de supprimer une tâche,
* de filtrer : *Toutes*, *Actives* et *Terminées*,
* de sauvegarder automatiquement les données dans le **localStorage** (les changements sont conservés même après la fermeture de la page).

Copiez‑collez le code ci‑dessous dans un fichier nommé `todo.html` et ouvrez‑le dans votre navigateur.

```html
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Todo List</title>
<style>
  body {font-family: Arial, sans-serif; margin: 20px;}
  #addForm input {padding: 5px; width: 250px;}
  #addForm button {padding: 5px 15px; cursor: pointer;}
  #taskList li {display: flex; align-items: center; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid #ccc;}
  #taskList li .completed {text-decoration: line-through; color: #777;}
  #filter {margin: 10px 0; padding: 5px; cursor: pointer;}
</style>
</head>
<body>

<h2>Mon To‑Do List</h2>

<form id="addForm">
  <input type="text" id="taskInput" placeholder="Nouvelle tâche...">
  <button type="submit">Ajouter</button>
</form>

<select id="filter">
  <option value="all">Toutes</option>
  <option value="active">Actives</option>
  <option value="completed">Terminées</option>
</select>

<ul id="taskList"></ul>

<script>
// ---------- Données de la liste ----------
let tasks = [];   // tableau d'objets {text, completed}

// ---------- Fichier de stockage ----------
const STORAGE_KEY = 'todoTasks';

// ---------- Initialisation ----------
function loadTasks() {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) {
    tasks = JSON.parse(saved);
  }
}
function saveTasks() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
}

// ---------- Render la liste ----------
function renderList() {
  const list = document.getElementById('taskList');
  list.innerHTML = '';          // vider la liste

  tasks.forEach((task, idx) => {
    const li = document.createElement('li');

    // checkbox
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.addEventListener('change', () => toggleTask(idx));

    // texte de la tâche
    const span = document.createElement('span');
    span.textContent = task.text;

    // bouton supprimer
    const delBtn = document.createElement('button');
    delBtn.textContent = '✕';
    delBtn.style.marginLeft = '8px';
    delBtn.addEventListener('click', () => deleteTask(idx));

    // classe pour les tâches terminées
    if (task.completed) li.classList.add('completed');

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(delBtn);
    list.appendChild(li);
  });
}

// ---------- Gestion d'une tâche ----------
function addTask(text) {
  const trimmed = text.trim();
  if (!trimmed) return;
  tasks.push({ text: trimmed, completed: false });
  saveTasks();
  renderList();
  // vider le champ
  document.getElementById('taskInput').value = '';
}

function toggleTask(idx) {
  tasks[idx].completed = !tasks[idx].completed;
  saveTasks();
  renderList();
}

function deleteTask(idx) {
  tasks.splice(idx, 1);
  saveTasks();
  renderList();
}

// ---------- Gestion du filtre ----------
function setFilter(filter) {
  // Mettre à jour la sélection du <select>
  document.getElementById('filter').value = filter;

  // Faire correspondre la vue affichée
  tasks.forEach((task, idx) => {
    if (filter === 'all') return; // afficher tout
    if (filter === 'active' && task.completed) return;
    if (filter === 'completed' && !task.completed) return;
    // sinon on masque
    tasks.splice(idx, 1);
  });

  saveTasks();
  renderList();
}

// ---------- Évènements de la page ----------
document.getElementById('addForm').addEventListener('submit', e => {
  e.preventDefault();
  const input = document.getElementById('taskInput');
  addTask(input.value);
});

document.getElementById('filter').addEventListener('change', e => {
  setFilter(e.target.value);
});

// ---------- Chargement initial ----------
loadTasks();
renderList();
</script>

</body>
</html>
```

### Comment ça fonctionne ?

1. **Ajouter** – Le texte entré dans le champ est ajouté à la liste.  
2. **Cochez** – Le bouton *✕* supprime la tâche. Le bouton checkbox bascule son état.  
3. **Filtrer** – Le sélecteur *Toutes / Actives / Terminées* affiche uniquement les tâches qui correspondent.  
4. **Persisté** – À chaque modification, la liste est sauvegardée dans le `localStorage` et la vue est reconstruite automatiquement.  

Bonne utilisation ! 🚀

Voici une petite application **To‑Do List** totalement dans un seul fichier HTML :  

```html
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>To‑Do List</title>
<style>
  body {font-family: Arial, sans-serif; margin:20px; background:#f4f4f4;}
  h1 {text-align:center;}
  .form {display:flex; max-width:600px; margin:auto; background:#fff; padding:10px; border-radius:5px; box-shadow:0 2px 5px rgba(0,0,0,.1);}
  .form input[type=text] {flex:1; padding:8px; font-size:16px; border:1px solid #ccc; border-radius:4px 0 0 4px;}
  .form button {padding:8px 12px; font-size:16px; border:none; background:#007BFF; color:#fff; border-radius:0 4px 4px 0; cursor:pointer;}
  .form button:hover {background:#0056b3;}
  .list {max-width:600px; margin:auto; background:#fff; padding:10px; border-radius:5px; box-shadow:0 2px 5px rgba(0,0,0,.1);}
  .task {display:flex; justify-content:space-between; align-items:center; padding:10px; background:#e9ecef; margin-bottom:5px; border-radius:4px; cursor:pointer;}
  .task.completed {text-decoration:line-through; color:#777;}
  .task .btn {font-size:14px; padding:4px 8px; border-radius:3px; cursor:pointer;}
  .task .btn.delete {background:#dc3545; color:#fff;}
  .task .btn.completed {background:#28a745; color:#fff;}
</style>
</head>
<body>

<h1>To‑Do List</h1>

<div class="form">
  <input type="text" id="taskInput" placeholder="Nouvelle tâche...">
  <button id="addBtn">Ajouter</button>
</div>

<div class="list" id="list"></div>

<div class="filter">
  <button data-filter="all" class="active">Toutes</button>
  <button data-filter="active">Actives</button>
  <button data-filter="completed">Terminées</button>
</div>

<script>
const STORAGE_KEY = 'todoList';
let tasks = [];

// Récupération des tâches depuis le localStorage
function loadTasks() {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved) tasks = JSON.parse(saved);
}

// Sauvegarde des tâches dans le localStorage
function saveTasks() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
}

// Génère un ID unique
function nextId() {
  return Math.max(...tasks.map(t => t.id)) + 1 || 1;
}

// Affiche les tâches dans le DOM
function renderTasks() {
  const listEl = document.getElementById('list');
  listEl.innerHTML = '';
  tasks.forEach(task => {
    const div = document.createElement('div');
    div.className = 'task' + (task.checked ? ' completed' : '');
    div.innerHTML = `
      <span>${task.text}</span>
      <button class="btn delete" data-id="${task.id}">✕</button>
    `;
    // Bouton "compléter"
    const checkBtn = document.createElement('button');
    checkBtn.className = 'btn completed';
    checkBtn.textContent = task.checked ? '✔' : '✖';
    checkBtn.addEventListener('click', () => {
      task.checked = !task.checked;
      div.classList.toggle('completed', task.checked);
      saveTasks();
    });
    // Bouton "supprimer"
    const delBtn = document.createElement('button');
    delBtn.className = 'btn delete';
    delBtn.textContent = '✕';
    delBtn.addEventListener('click', () => {
      tasks = tasks.filter(t => t.id !== task.id);
      renderTasks();
      saveTasks();
    });
    div.appendChild(checkBtn);
    div.appendChild(delBtn);
    listEl.appendChild(div);
  });
}

// Ajoute une nouvelle tâche
document.getElementById('addBtn').addEventListener('click', () => {
  const input = document.getElementById('taskInput');
  const text = input.value.trim();
  if (text) {
    const newTask = {id: nextId(), text, checked: false};
    tasks.push(newTask);
    input.value = '';
    renderTasks();
    saveTasks();
  }
});

// Gère la coche
document.getElementById('list').addEventListener('click', e => {
  if (e.target.classList.contains('btn')) {
    const task = e.target.closest('.task');
    const id = task.dataset.id;
    const idx = tasks.findIndex(t => t.id === id);
    if (idx !== -1) {
      tasks[idx].checked = !tasks[idx].checked;
      renderTasks();
      saveTasks();
    }
  }
});

// Gère la suppression
document.getElementById('list').addEventListener('click', e => {
  if (e.target.classList.contains('btn')) {
    const task = e.target.closest('.task');
    const id = task.dataset.id;
    tasks = tasks.filter(t => t.id !== id);
    renderTasks();
    saveTasks();
  }
});

// Filtrer les tâches
document.querySelectorAll('.filter button').forEach(btn => {
  btn.addEventListener('click', () => {
    const filter = btn.dataset.filter;
    document.querySelectorAll('.filter button').forEach(b => b.classList.toggle('active', b === btn));
    tasks = filter === 'completed' ? tasks.filter(t => t.checked) :
             filter === 'active' ? tasks.filter(t => !t.checked) :
             tasks.filter(t => !t.checked || t.checked);
    renderTasks();
  });
});

// Chargement au démarrage
loadTasks();
renderTasks();
</script>

</body>
</html>
```

Copiez ce code dans un fichier `todo.html`, ouvrez‑le dans votre navigateur et vous pourrez :

- **Ajouter** une tâche  
- **Cocher** la tâche comme terminée / la décocher  
- **Supprimer** une tâche  
- **Filtrer** les tâches : toutes, actives ou terminées  

Les changements sont sauvegardés dans `localStorage`, donc les données persistent même après la fermeture et la réouverture du navigateur. Enjoy!

